package com.tuckersoft.branchengine.exception; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e,HttpServletRequest r){return ResponseEntity.status(e.getStatus()).body(new ErrorResponse(e.getError(),e.getMessage(),Instant.now(),r.getRequestURI()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(f->f.getField()+": "+f.getDefaultMessage()).orElse("Validación fallida"); return ResponseEntity.badRequest().body(new ErrorResponse("VALIDATION_ERROR",m,Instant.now(),r.getRequestURI()));} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> generic(Exception e,HttpServletRequest r){return ResponseEntity.status(500).body(new ErrorResponse("INTERNAL_ERROR",e.getMessage()==null?"Error interno":e.getMessage(),Instant.now(),r.getRequestURI()));} }
